  // 在这里实现
}

solution:
function latestById(events) {
  const positions = new Map();
  const result = [];
  for (const event of events) {
    if (!positions.has(event.id)) { positions.set(event.id,result.length); result.push(event); }
    else { const index=positions.get(event.id); if (event.ts >= result[index].ts) result[index]=event; }
  }
  return result;
}

