}

solution:
async function resumeUpload(bytes, chunkSize, getOffset, sendChunk) {
  if (!Number.isInteger(chunkSize) || chunkSize <= 0) throw new RangeError("分片大小无效");
  let offset=await getOffset();
  if (!Number.isInteger(offset) || offset<0 || offset>bytes.length) throw new RangeError("偏移无效");
  while (offset<bytes.length) {
    const part=bytes.subarray(offset,Math.min(offset+chunkSize,bytes.length));
    await sendChunk(offset,part);
    offset+=part.length;
  }
  return bytes.length;
}

