function createRecentCache(limit) {
  if(!Number.isInteger(limit)||limit<=0) throw new RangeError("limit 无效");
  const items=new Map();
  const refresh=(key,value)=>{items.delete(key);items.set(key,value)};
  return {
    put(key,value){refresh(key,value);if(items.size>limit) items.delete(items.keys().next().value)},
